FOOTERS = (7, 8, 9, 10, 12)          # footer sensitivity set (t57/t59)
TRAILERS = (12, 13, 11)              # identity trailer width: 12B triple, 13B triple+marker, 11B (falsifiable)
MAXI = 1 << 20


class Check(Exception):
    """Verification failure (exit code 1)."""


class Usage(Exception):
    """Usage / fatal environment failure (exit code 2)."""


def ck(ok: bool, detail) -> None:
    if not ok:
        raise Check(detail)


def sha(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def jload(p: pathlib.Path) -> dict:
    if not p.exists():
        raise Usage(f"missing artifact: {p}")
    return json.loads(p.read_text(encoding="utf-8"))


# --------------------------------------------------------------------------------------- decoding


def codec_env() -> dict:
    sys.argv = ["fm24_dump"]
    return runpy.run_path(str(DUMP), run_name="t73_notmain")


def payload(env: dict, archive: str, table: int) -> bytes:
    """Delegate to fm24_dump.load_payload (member bounds + frame size selector, t38/E80 fixed)."""
    return env["load_payload"](env["_reader"](), archive, table)


def payload_info(raw: bytes) -> dict:
    return {"payload_bytes": len(raw), "payload_sha256": sha(raw), "header8": raw[:8].hex(),
            "count_u32_at_8": struct.unpack_from("<I", raw, 8)[0],
            "footer8": raw[-8:].hex()}


# --------------------------------------------------------------------------------- frame closure


def triple_points(raw: bytes, n: int) -> list[tuple[int, int, int]]:
    """All (ordinal, absolute position, uid) points with the shape ordinal|u32|u32 and 0 <= ord < n."""
    pts: list[tuple[int, int, int]] = []
    L = len(raw)
    for k in range(4):
        m = (L - k) // 4
        if m < 3:
            continue
        for i in range(m - 2):
            pos = k + 4 * i
            if pos + 12 > L:
                break
            uid = struct.unpack_from("<I", raw, pos + 4)[0]
            if uid == 0:
                continue
            if struct.unpack_from("<I", raw, pos + 8)[0] != uid:
                continue
            ordv = struct.unpack_from("<I", raw, pos)[0]
            if ordv >= n:
                continue
            pts.append((ordv, pos, uid))
    pts.sort()
    return pts


def path_count(raw: bytes, pts, header: int, footer: int, trailer: int, markers, nonzero: bool,
               increasing: bool, recover: bool = False):
    """t57/t59 four-alignment DP: count non-overlapping full铺 paths, optionally recover row starts."""
    n = struct.unpack_from("<I", raw, 8)[0]
    groups: list[list[tuple[int, int]]] = [[] for _ in range(n)]
    for ordv, pos, uid in pts:
        groups[ordv].append((pos, uid))
    prev: list[tuple[int, int, int]] = []
    back: list[dict] = []
    limit = len(raw) - footer
    for i, group in enumerate(groups):
        cur: list[tuple[int, int, int]] = []
        bk: dict[int, int | None] = {}
        prefix = [0]
        apos: list[int] = []
        if not increasing:
            for p, _, c in prev:
                apos.append(p)
                prefix.append(prefix[-1] + c)
        for pos, uid in group:
            end = pos + trailer
            if pos < header or end > limit:
                continue
            if i == len(groups) - 1 and end != limit:
                continue
            if nonzero and uid == 0:
                continue
            if markers is not None:
                if pos + 12 >= len(raw) or raw[pos + 12] not in markers:
                    continue
            if i == 0:
                cnt, wit = 1, None
            elif not increasing:
                cnt, wit = prefix[bisect_right(apos, pos - trailer)], None
            else:
                cnt, wit = 0, None
                for p, v, c in prev:
                    if p > pos - trailer:
                        break
                    if v < uid:
                        cnt += c
                        wit = p
            if cnt:
                cur.append((pos, uid, min(MAXI, cnt)))
                if recover:
                    bk[pos] = wit
        if not cur:
            return {"paths": 0, "first_dead_ordinal": i,
                    "first_rejected_candidate": list(group[0]) if group else None}, None
        if recover:
            back.append(bk)
        prev = cur
    total = min(MAXI, sum(v for _, _, v in prev))
    starts = None
    if recover and total == 1:
        pos = prev[0][0]
        starts = [pos]
        for bk in reversed(back[:-1]):
            pos = bk[pos]
            starts.append(pos)
        starts.reverse()
    return {"paths": total, "saturated": total == MAXI, "first_dead_ordinal": None}, starts


def sensitivity(raw: bytes, n: int, stride: int | None) -> dict:
    """Full footer/trailer sensitivity matrix (path counts), mirroring the t57/t59 tables."""
    pts = triple_points(raw, n)
    out: dict[str, dict] = {}
    for trailer in TRAILERS:
        for footer in FOOTERS:
            markers = {0} if trailer == 13 else None
            key = f"trailer_{trailer}_footer_{footer}"
            if trailer == 11:
                out[key] = {"paths": 0, "note": "11B cannot hold ordinal|UID|UID (documented negative)"}
                continue
            if stride is not None and trailer == 12:
                ok = 0
                h = len(raw) - n * stride - footer
                if h >= 0:
                    for i in range(n):
                        b = h + i * stride + stride - 12
                        if b + 12 > len(raw):
                            break
                        j, u, v = struct.unpack_from("<III", raw, b)
                        if j == i and u == v and u:
                            ok += 1
                out[key] = {"paths": 1 if ok == n else 0, "fixed_stride_rows_with_identity": ok}
            else:
                res, _ = path_count(raw, pts, 13, footer, trailer, markers, True, True)
                out[key] = res
    out["_triple_points"] = len(pts)
    out["_cap"] = MAXI
    return out


def fixed_frames(raw: bytes, n: int) -> list[dict]:
    """Every (header, footer, stride, trailer) partition that closes arithmetically."""
    L = len(raw)
    out = []
    for footer in FOOTERS:
        for header in range(8, 22):
            rem = L - header - footer
            if rem <= 0 or rem % n:
                continue
            stride = rem // n
            if stride < 12 or stride > 8192:
                continue
            for trailer in TRAILERS:
                p = stride - trailer
                if p < 0:
                    continue
                good = 0
                marker = Counter()
                for i in range(n):
                    b = header + i * stride + p
                    if b + 12 > L:
                        break
                    j, u, v = struct.unpack_from("<III", raw, b)
                    if j != i or u != v or u == 0:
                        break
                    good += 1
                    if b + 12 < L:
                        marker[raw[b + 12]] += 1
                out.append({
                    "header": header, "footer": footer, "stride": stride, "trailer": trailer,
                    "business_width": stride - trailer - (1 if trailer == 13 else 0),
                    "identity_rows": good, "identity_all": good == n,
                    "marker_hist": {hex(k): v for k, v in marker.most_common(4)},
                    "marker_constant_zero": len(marker) == 1 and 0 in marker,
                    "equation": f"{header} + {n} * {stride} + {footer} = {header + n * stride + footer}",
                    "closes": header + n * stride + footer == L,
                })
    return out


def pick_fixed(raw: bytes, n: int, anchors: dict, budget: int | None) -> tuple[dict, list[dict]]:
    """Choose the native partition.  Scoring uses only independent facts, never preference alone."""
    cands = [c for c in fixed_frames(raw, n) if c["closes"]]
    for c in cands:
        c["anchors_hold"] = anchor_holds(raw, n, c, anchors)
        c["budget_ok"] = (budget is not None and c["business_width"] == budget)
    cands.sort(key=lambda c: (not c["anchors_hold"], not c["identity_all"],
                              not c["marker_constant_zero"], not c["budget_ok"],
                              c["trailer"] != 12, c["header"] != 14))
    return cands[0], cands


def anchor_holds(raw: bytes, n: int, frame: dict, anchors: dict) -> bool:
    """A framing is only acceptable if every pre-existing fm24_dump.FIELDS anchor reads correctly."""
    if not anchors:
        return True
    header, stride = frame["header"], frame["stride"]
    for name, off in anchors.items():
        rel = stride + off if off < 0 else off
        if rel < 0 or rel + 4 > stride:
            return False
        want_row, want_uid = (None, None)
        for i in (0, 1, n - 1):
            b = header + i * stride + rel
            v = struct.unpack_from("<I", raw, b)[0]
            if name == "rdui":
                if v != i:
                    return False
            elif name == "duni":
                if v == 0 or v != struct.unpack_from("<I", raw, b + 4)[0]:
                    return False
            elif v == 0 and name not in ("rdui_suffix",):
                return False
    return True


def walk_fixed(raw: bytes, frame: dict, n: int) -> list[dict]:
    header, stride = frame["header"], frame["stride"]
    trailer = frame["trailer"]
    p = stride - trailer
    rows = []
    for i in range(n):
        b = header + i * stride
        body = raw[b:b + stride]
        j, u, v = struct.unpack_from("<III", body, p)
        if j != i or u != v or u == 0:
            raise Check(f"row {i}: identity triple mismatch at {b + p}")
        rows.append({"ordinal": i, "start": b, "end": b + stride, "uid": u,
                     "body_start": b, "body_len": p, "identity_at": b + p,
                     "marker": body[p + 12] if trailer == 13 else None})
    return rows


# ------------------------------------------------------------------------------- variable tables


def _u32(raw: bytes, p: int) -> int:
    return struct.unpack_from("<I", raw, p)[0]


def parse_variable_row(raw: bytes, cur: int, grammar: dict):
    """Deterministic row parse for the recovered 'strings + rate + counted items + 13B trailer' shape."""
    p = cur
    L = len(raw)
    strings = []
    for _ in range(grammar["nstr"]):
        if p + 4 > L:
            return None
        ln = _u32(raw, p)
        p += 4
        if ln > 4096 or p + ln > L:
            return None
        strings.append(raw[p:p + ln])
        p += ln
    rate = None
    if grammar["rate"]:
        if p + 4 > L:
            return None
        rate = struct.unpack_from("<f", raw, p)[0]
        p += 4
    cw = grammar["cw"]
    if p + cw > L:
        return None
    cnt = int.from_bytes(raw[p:p + cw], "little")
    p += cw
    if cnt > 200000:
        return None
    items_at = p
    p += cnt * grammar["iw"]
    if p + 13 > L:
        return None
    j, u, v = struct.unpack_from("<III", raw, p)
    marker = raw[p + 12]
    return {"strings": strings, "rate": rate, "count": cnt, "items_at": items_at,
            "items_len": cnt * grammar["iw"], "identity_at": p, "ordinal": j, "uid": u,
            "uid2": v, "marker": marker, "end": p + 13, "header_len": items_at - cur}


def walk_variable(raw: bytes, header: int, footer: int, grammar: dict) -> list[dict] | None:
    n = _u32(raw, 8)
    p = header
    limit = len(raw) - footer
    rows = []
    last_uid = 0
    for i in range(n):
        r = parse_variable_row(raw, p, grammar)
        if r is None:
            return None
        if r["identity_at"] + 13 > limit:
            return None
        if r["ordinal"] != i or r["uid"] != r["uid2"] or r["uid"] == 0 or r["uid"] <= last_uid:
            return None
        if r["marker"] != 0:
            return None
        if r["end"] > limit:
            return None
        last_uid = r["uid"]
        r["ordinal"] = i
        r["start"] = p
        rows.append(r)
        p = r["end"]
    if p != limit:
        return None
    return rows


def search_variable(raw: bytes) -> dict:
    """Grid search over header/footer/grammar; only a full-payload closure with monotone UIDs wins."""
    n = _u32(raw, 8)
    hits = []
    for nstr in range(0, 6):
        for rate in (1, 0):
            for cw in (4, 2, 1):
                for iw in range(1, 17):
                    grammar = {"nstr": nstr, "rate": rate, "cw": cw, "iw": iw}
                    first = parse_variable_row(raw, 14, grammar)
                    if first is None or first["ordinal"] != 0:
                        continue
                    for footer in FOOTERS:
                        for header in range(8, 20):
                            if header != 14:
                                continue  # header only affects row 0 start; 14 is the table header
                            rows = walk_variable(raw, header, footer, grammar)
                            if rows is not None:
                                hits.append({"header": header, "footer": footer,
                                             "grammar": grammar, "rows": rows})
    # dedupe by (grammar, footer)
    seen, uniq = set(), []
    for h in hits:
        key = (json.dumps(h["grammar"], sort_keys=True), h["footer"], h["header"])
        if key in seen:
            continue
        seen.add(key)
        uniq.append(h)
    return {"candidates": len(uniq), "best": uniq[0] if uniq else None,
            "all": [{"header": h["header"], "footer": h["footer"], "grammar": h["grammar"],
                     "row_bytes": [r["end"] - r["start"] for r in h["rows"][:3]]} for h in uniq[:12]]}


# -------------------------------------------------------------------------------------- profiling


def _f32(b: bytes) -> float:
    return struct.unpack("<f", b)[0]


def profile_columns(raw: bytes, frame: dict, n: int) -> list[dict]:
    """Per-offset domain profile over the business area (identity/trailer excluded)."""
    header, stride, trailer = frame["header"], frame["stride"], frame["trailer"]
    bw = stride - trailer
    cols = []
    for o in range(bw):
        vals = [raw[header + i * stride + o] for i in range(n)]
        cnt = Counter(vals)
        cols.append({"offset": o, "width": 1, "kind": "u8", "distinct": len(cnt),
                     "all_zero": len(cnt) == 1 and 0 in cnt,
                     "all_ff": len(cnt) == 1 and 255 in cnt,
                     "zero_frac": round(cnt.get(0, 0) / n, 6), "one_frac": round(cnt.get(1, 0) / n, 6),
                     "ff_frac": round(cnt.get(255, 0) / n, 6),
                     "min": min(vals), "max": max(vals),
                     "mode": cnt.most_common(1)[0][0], "mode_count": cnt.most_common(1)[0][1],
                     "top": [[v, c] for v, c in cnt.most_common(6)]})
    wins = []
    for width in (2, 3, 4):
        for o in range(0, bw - width + 1):
            raw_vals = [raw[header + i * stride + o: header + i * stride + o + width] for i in range(n)]
            u = [int.from_bytes(b, "little") for b in raw_vals]
            s = [int.from_bytes(b, "little", signed=True) for b in raw_vals]
            cnt = Counter(u)
            rec = {"offset": o, "width": width, "kind": f"u{width * 8}", "distinct": len(cnt),
                   "all_zero": len(cnt) == 1 and 0 in cnt,
                   "sentinel_ff": sum(1 for x in u if x == (1 << (width * 8)) - 1),
                   "zero_frac": round(cnt.get(0, 0) / n, 6),
                   "min_u": min(u), "max_u": max(u), "min_i": min(s), "max_i": max(s),
                   "mode": cnt.most_common(1)[0][0], "mode_count": cnt.most_common(1)[0][1],
                   "monotonic_strict": all(u[i + 1] > u[i] for i in range(n - 1)) if n > 1 else False,
                   "top": [[v, c] for v, c in cnt.most_common(5)]}
            if width == 4:
                f = [_f32(b) for b in raw_vals]
                fin = [x for x in f if math.isfinite(x)]
                rec["f32"] = {"finite": len(fin), "nan": len(f) - len(fin),
                              "min": min(fin) if fin else None, "max": max(fin) if fin else None,
                              "abs_lt_180": sum(1 for x in fin if abs(x) < 180),
                              "in_0_1": sum(1 for x in fin if 0.0 <= x <= 1.0)}
                rec["kind"] = "u32/i32/f32"
            wins.append(rec)
    return cols + wins


def profile_variable(rows: list[dict], n: int) -> dict:
    nstr = len(rows[0]["strings"]) if rows else 0
    sstats = []
    for k in range(nstr):
        lens = [len(r["strings"][k]) for r in rows]
        nonempty = [r["strings"][k] for r in rows if r["strings"][k]]
        sstats.append({"slot": k, "empty": n - len(nonempty), "min_len": min(lens), "max_len": max(lens),
                       "examples": [b.decode("utf-8", "replace") for b in nonempty[:4]],
                       "distinct": len(set(nonempty))})
    rates = [r["rate"] for r in rows if r["rate"] is not None]
    counts = [r["count"] for r in rows]
    items = []
    kinds, years, values = Counter(), [], []
    for r in rows:
        iw = r["items_len"] // r["count"] if r["count"] else 0
        for j in range(r["count"]):
            at = r["items_at"] + j * iw
            kinds[r["header_len"] * 0 + iw] += 1
    return {
        "strings": sstats, "n_strings": nstr,
        "rate": {"n": len(rates), "min": min(rates) if rates else None,
                 "max": max(rates) if rates else None,
                 "nonzero": sum(1 for x in rates if x)},
        "item_count": {"min": min(counts), "max": max(counts), "total": sum(counts),
                       "hist_top": [[v, c] for v, c in Counter(counts).most_common(5)]},
        "row_bytes": {"min": min(r["end"] - r["start"] for r in rows),
                      "max": max(r["end"] - r["start"] for r in rows),
                      "distinct": len({r["end"] - r["start"] for r in rows})},
        "item_widths_seen": sorted(kinds),
    }


def profile_item_bytes(raw: bytes, rows: list[dict], iw: int) -> list[dict]:
    """Byte-level decomposition of one history item (only when every row reports the same width)."""
    vals = defaultdict(list)
    for r in rows:
        if iw <= 0:
            continue
        for j in range(r["count"]):
            at = r["items_at"] + j * iw
            for o in range(iw):
                vals[o].append(raw[at + o])
    out = []
    for o in range(iw):
        c = Counter(vals[o])
        out.append({"item_offset": o, "distinct": len(c), "min": min(vals[o]), "max": max(vals[o]),
                    "top": [[v, k] for v, k in c.most_common(4)]})
    return out


# ------------------------------------------------------------------------------- foreign-key sets


def fk_domains(env: dict, need: dict) -> dict:
    """Impact: {table: {archive: uid map}} for target tables we can frame here + ordinal domains."""
    out: dict[str, dict] = {}
    priors = _priors()
    for tid, info in need.items():
        dom = {"ordinal_domain": [0, info["count"] - 1], "count": info["count"],
               "provenance": info["provenance"], "uid": {}}
        if info.get("frame"):
            for archive in ("client", "server"):
                try:
                    raw = payload(env, archive, tid)
                except Exception as exc:  # noqa: BLE001 - reported, never silently dropped
                    dom[f"{archive}_error"] = str(exc)
                    continue
                n = struct.unpack_from("<I", raw, 8)[0]
                frame = info["frame"](raw, n)
                if frame is None:
                    continue
                rows = walk_fixed(raw, frame, n)
                dom["uid"][archive] = {r["uid"]: r["ordinal"] for r in rows}
                dom[f"{archive}_identity_sha256"] = sha(
                    b"".join(struct.pack("<II", r["ordinal"], r["uid"]) for r in rows))
        out[str(tid)] = dom
    return out


def _priors() -> dict:
    """Upstream row-frame priors (evidence snapshot); used only as prior, never as ground truth."""
    priors: dict[int, dict] = {}
    small = jload(SMALL)["tables"]
    for _, it in small.items():
        tid = it["table_id"]
        rb = it.get("row_boundary") or {}
        priors[tid] = {"count": it["record_count"], "payload": it["payload_size"],
                       "stride": rb.get("stride"), "header": rb.get("header_size"),
                       "footer": rb.get("footer_size"), "model": rb.get("status"),
                       "provenance": f"evidence/fm24/reports/dbdat_decode/db_tables_small.json#{tid}"}
    big = jload(BIG)["tables"]
    for k, it in big.items():
        if k == "extra_3":
            continue
        tid = int(k)
        model = it.get("model") or {}
        rec = priors.setdefault(tid, {})
        rec.setdefault("count", (model.get("record_count") if isinstance(model, dict) else None))
        rec.setdefault("stride", (model.get("stride_bytes") if isinstance(model, dict) else None))
        rec.setdefault("header", (model.get("header_bytes") if isinstance(model, dict) else None))
        rec.setdefault("footer", (model.get("footer_bytes") if isinstance(model, dict) else None))
        rec.setdefault("payload", (model.get("payload_size") if isinstance(model, dict) else None))
        rec.setdefault("model", "big prior")
        rec["provenance"] = f"evidence/fm24/reports/dbdat_decode/db_tables_big.json#{k}"
    priors[10] = priors.get(10) or {"count": 251, "provenance": "db_tables_small.json#10"}
    priors[3] = priors.get(3) or {"count": 84259, "provenance": "db_tables_big.json#3"}
    priors[24] = priors.get(24) or {"count": None, "provenance": "unknown (negative result in E37)"}
    return priors


def t05_budget(tid: int) -> dict:
    """Static reader business-width budget from repo artifact (t05 L3-static reader scan)."""
    if not T05_WIDTHS.exists():
        return {}
    for it in jload(T05_WIDTHS).get("results", []):
        if it.get("type_id") == tid:
            return {"budgets": it.get("budgets"), "reader": it.get("reader"), "body": it.get("body"),
                    "seq": it.get("seq"), "provenance": "scratch/t05/reader_widths.json (t05 L3-static reader scan)"}
    return {}


def t12_static(tid: int) -> dict:
    """Static 4CC/reader pairings from repo artifact reports/t12_field_names.json (E53/E55)."""
    if not T12.exists():
        return {}
    doc = jload(T12)
    out: dict[str, dict] = {}
    for s in doc.get("slots", []):
        if s.get("type_id") != tid:
            continue
        if s.get("confidence") not in ("readpair", "ref_only", "chain_unique"):
            continue
        if not s.get("field"):
            continue
        out.setdefault(s["archive"], {})[s["row_off"]] = {
            "field": s["field"], "codes": s.get("codes"), "width": s["width"],
            "object_off": s.get("object_off"), "confidence": s["confidence"],
            "evidence": s.get("evidence"), "why": s.get("why")}
    return out


# --------------------------------------------------------------------------------- alignment


def schema_fields(xml: str, entity_id: str) -> list[dict]:
    doc = jload(MASTER)
    for ent in doc["entities"][xml]:
        if ent.get("id") == entity_id:
            return ent["fields"]
    raise Check(f"{xml}#{entity_id} not in master.json")


def scoped_enum(field: dict) -> set | None:
    er = field.get("enum_ref")
    if not er:
        return None
    doc = jload(MASTER)
    vals = doc.get("enums", {}).get(er)
    if not vals:
        return None
    out = set()
    for v in vals["values"]:
        for key in ("enum", "enum_id"):
            try:
                if v.get(key) is not None:
                    out.add(int(v[key]))
            except (TypeError, ValueError):
                pass
    return out


def fk_gate(values: list[int], dom: dict, width: int) -> dict:
    sentinel = (1 << (width * 8)) - 1
    live = [v for v in values if v != sentinel]
    nulls = len(values) - len(live)
    lo, hi = dom["ordinal_domain"]
    in_dom = sum(1 for v in live if lo <= v <= hi)
    uid_hits = 0
    uid_map = dom.get("uid", {}).get("client") or {}
    if uid_map:
        uid_hits = sum(1 for v in live if v in uid_map)
    return {"tested": len(values), "legal_zero": sum(1 for v in live if v == 0),
            "null_sentinel_ff": nulls, "live": len(live),
            "in_target_ordinal_domain": in_dom, "out_of_domain": len(live) - in_dom,
            "wrong_uid_control_hits": uid_hits if uid_map else None,
            "target_count": dom["count"], "target_provenance": dom["provenance"],
            "max_live": max(live) if live else None}


def align(env, archive: str, tid: int, raw: bytes, frame: dict, n: int, rows: list[dict],
          cols: list[dict]) -> dict:
    """Data-side alignment: static anchor (if any) first, then declared-type/domain gates."""
    xml = TABLES[tid]["xml"]
    fields = schema_fields(xml, TABLES[tid]["id"])
    static = t12_static(tid).get(archive, {})
    budgets = t05_budget(tid)
    updir = {}
    out_fields = []
    prof_index = {(c["offset"], c["width"]): c for c in cols}

    def col(o, w):
        return prof_index.get((o, w))

    fk_targets = {2: {"count": n, "provenance": "this run (framed)", "frame": None},
                  5: {"count": None}, 19: {"count": None}, 21: {"count": 48413,
                                                                "provenance": "evidence/db_tables_big.json#21"},
                  23: {"count": 278, "provenance": "evidence/db_tables_small.json#23"},
                  25: {"count": 7047, "provenance": "evidence/db_tables_small.json#25"},
                  10: {"count": 251, "provenance": "evidence/db_tables_small.json#10"},
                  3: {"count": 84259, "provenance": "evidence/db_tables_big.json#3"},
                  27: {"count": 334, "provenance": "evidence/db_tables_small.json#27"},
                  8: {"count": 126, "provenance": "evidence/db_tables_small.json#8"},
                  47: {"count": 2488, "provenance": "evidence/db_tables_small.json#47"}}
    # region/continent/currency counts are framed in this run
    try:
        fk_targets[5]["count"] = struct.unpack_from("<I", payload(env, archive, 5), 8)[0]
        fk_targets[19]["count"] = struct.unpack_from("<I", payload(env, archive, 19), 8)[0]
    except Exception:  # noqa: BLE001 - domain stays null, gates degrade to "unknown"
        pass

    for idx, f in enumerate(fields):
        code = f["field"]
        ftype = f.get("type")
        rec = {"xml_index": idx, "field": code, "name": f.get("name"), "type": ftype,
               "declared": {k: f[k] for k in ("min_value", "max_value", "max_length", "hint")
                            if k in f},
               "status": "unmapped", "slot": None, "grade": None, "evidence": [], "gate": None,
               "reason": None}
        if code in ("duni", "rdui"):
            off = frame["stride"] - (12 if code == "duni" else 12) + (0 if code == "rdui" else 4)
            rec.update(status="L1-structural", slot={"offset": off, "width": 4}, grade="L1",
                       evidence=[{"kind": "frame identity triple",
                                  "note": "ordinal|UID|UID self-proved on every row of this archive"}] +
                                 ([{"kind": "fm24_dump.FIELDS anchor", "offset": anchor_off(archive, tid, code)}]
                                  if anchor_off(archive, tid, code) is not None else []))
            out_fields.append(rec)
            continue
        if code in ("NDBC", "FDBC"):
            deps = [d.get("field") for d in f.get("dependencies", [])]
            rec.update(status="unmapped", reason=(
                f"editor-session counter; schema dependency {deps} means it only exists while a single "
                "record is being edited, so no per-row wire slot is expected (negative, not a gap)"))
            out_fields.append(rec)
            continue
        if code == "dbnm" or ftype == "string" and f.get("is_language_field"):
            rec.update(status="escalate_to_sol", reason=(
                "localized/DB name text: no length-prefixed string and no TLV tag exists in this "
                "archive's business area (byte scan found no printable run >= 4), so the value lives in "
                "the language/name layer; needs exe reader dispatch to bind"))
            out_fields.append(rec)
            continue
        if ftype in ("string",) or ftype == "list" or ftype == "colour":
            rec.update(status="escalate_to_sol", reason=(
                f"declared {ftype}: no matching wire shape in this archive's business area; needs "
                "exe reader/4CC dispatch"))
            out_fields.append(rec)
            continue

        # static anchor first (never XML order)
        anchor = static.get(idx) if isinstance(static.get(idx), dict) else None
        anchor = None
        for ro, info in static.items():
            if code in (info.get("codes") or []) or code == info.get("field"):
                anchor = dict(info, row_off=ro)
                break
        if anchor and anchor["width"] <= frame["stride"]:
            o, w = anchor["row_off"], anchor["width"]
            prof = col(o, w)
            gate = None
            status, grade = "candidate", "L3-inherited"
            if ftype in ("database_record_unique_id",) or f.get("database_table_type"):
                target = map_ref_table(f.get("database_table_type"))
                vals = [int.from_bytes(raw[frame["header"] + i * frame["stride"] + o:
                                            frame["header"] + i * frame["stride"] + o + 4], "little")
                        for i in range(n)]
                if target and target in fk_targets and fk_targets[target].get("count"):
                    gate = fk_gate(vals, {"ordinal_domain": [0, fk_targets[target]["count"] - 1],
                                          "count": fk_targets[target]["count"],
                                          "provenance": fk_targets[target]["provenance"],
                                          "uid": {}}, 4)
                    status = "L3-inherited" if gate["out_of_domain"] == 0 else "held"
                    if gate["out_of_domain"]:
                        grade = "L2"
            if ftype == "real":
                vals = [_f32(raw[frame["header"] + i * frame["stride"] + o:
                                 frame["header"] + i * frame["stride"] + o + 4]) for i in range(n)]
                fin = [x for x in vals if math.isfinite(x)]
                gate = {"tested": n, "finite": len(fin), "min": min(fin) if fin else None,
                        "max": max(fin) if fin else None}
                if not fin:
                    status = "held"
            if ftype == "integer" and ("min_value" in f or "max_value" in f):
                lo = int(f.get("min_value", -2 ** 31))
                hi = int(f.get("max_value", 2 ** 31))
                vals = [int.from_bytes(raw[frame["header"] + i * frame["stride"] + o:
                                           frame["header"] + i * frame["stride"] + o + w],
                                       "little", signed=True) for i in range(n)]
                bad = sum(1 for v in vals if v < lo or v > hi)
                gate = {"tested": n, "outside_declared_range": bad, "min": min(vals), "max": max(vals),
                        "declared": [lo, hi]}
                if bad:
                    status = "held"
            rec.update(status=status, grade=grade, slot={"offset": o, "width": w, "lane": 0},
                       evidence=[{"kind": "static artifact", "artifact": "reports/t12_field_names.json",
                                  "confidence": anchor["confidence"], "object_off": anchor.get("object_off"),
                                  "file_off": (anchor.get("evidence") or {}).get("file_off"),
                                  "access_va": (anchor.get("evidence") or {}).get("access_va"),
                                  "why": anchor.get("why"),
                                  "level": "L3 (editor.exe static, inherited from t12; not re-read in t73)"}],
                       gate=gate, profile=prof)
            out_fields.append(rec)
            continue

        # no static anchor: only report domain-compatible slots, never name them
        cands = []
        if ftype == "real":
            for c in cols:
                if c["width"] == 4 and c.get("f32") and c["f32"]["finite"] == n:
                    cands.append({"offset": c["offset"], "width": 4,
                                  "why": f"f32 finite on all {n} rows; range "
                                         f"[{round(c['f32']['min'], 6)}, {round(c['f32']['max'], 6)}]"})
        elif ftype in ("database_record_unique_id",):
            for c in cols:
                if c["width"] == 4 and c.get("sentinel_ff") is not None:
                    cands.append({"offset": c["offset"], "width": 4,
                                  "why": f"4B with {c['sentinel_ff']} 0xffffffff sentinels, "
                                         f"max_live={c['max_u'] if c['sentinel_ff'] == 0 else '-'}"})
        elif ftype == "integer" and ("min_value" in f or "max_value" in f):
            lo = int(f.get("min_value", -2 ** 31))
            hi = int(f.get("max_value", 2 ** 31))
            for c in cols:
                if c["width"] in (1, 2, 4) and c["min_i"] >= lo and c["max_i"] <= hi:
                    cands.append({"offset": c["offset"], "width": c["width"],
                                  "why": f"integer window inside declared [{lo},{hi}]"})
        if cands:
            rec.update(status="domain_compatible_but_unbound", candidates=cands[:8],
                       reason=("no static 4CC/reader anchor exists for this entity in the frozen "
                               "artifacts; a range coincidence is NOT a mapping (candidate only)"))
        else:
            rec.update(status="unmapped", reason="no slot of the declared type/shape in the business area")
        out_fields.append(rec)

    used = {(f["slot"] or {}).get("offset") for f in out_fields if f.get("slot")}
    slot_rows = []
    for c in cols:
        if c["width"] != 1 and c.get("f32") is None:
            continue
        owners = [f["field"] for f in out_fields if f.get("slot") and f["slot"]["offset"] == c["offset"]
                  and f["slot"]["width"] == c["width"]]
        slot_rows.append({"offset": c["offset"], "width": c["width"], "kind": c["kind"],
                          "profile": c, "claimed_by": owners})
    return {"fields": out_fields, "slots": slot_rows, "static_artifact": bool(static),
            "budget": budgets}


