def printable_runs(raw: bytes, frame: dict, n: int) -> dict:
    """Evidence that the business area carries no inline text (names must live in a language layer)."""
    header, stride, bw = frame["header"], frame["stride"], frame["stride"] - frame["trailer"]
    best = 0
    runs = 0
    for i in range(min(n, 5000)):
        base = header + i * stride
        cur = 0
        for o in range(bw):
            b = raw[base + o]
            if 32 <= b < 127:
                cur += 1
                best = max(best, cur)
            else:
                if cur >= 4:
                    runs += 1
                cur = 0
        if cur >= 4:
            runs += 1
    return {"rows_scanned": min(n, 5000), "printable_runs_ge4": runs, "longest_printable_run": best}


