def check_anchors(raw: bytes, frame: dict, rows: list[dict], anchors: dict) -> dict:
    out = {}
    header, stride = frame["header"], frame["stride"]
    n = len(rows)
    for name, off in anchors.items():
        rel = stride + off if off < 0 else off
        ok = 0
        bad = None
        for i in range(n):
            b = header + i * stride + rel
            v = struct.unpack_from("<I", raw, b)[0]
            good = (v == i) if name == "rdui" else (v == rows[i]["uid"])
            if good:
                ok += 1
            elif bad is None:
                bad = {"row": i, "value": v}
        out[name] = {"anchor_offset": off, "rows_ok": ok, "rows": n,
                     "status": "PASS" if ok == n else "FAIL", "first_bad": bad}
    return out


