        raw = load_payload(archive, tid)
        fc = frame_closure(raw, min_rows=1)
        cand = [c for c in fc["closed"] if c["mode"] == "ordinal+uidpair"]
        if len(cand) != 1:
            out = {"ok": False, "why": f"frame not unique ({len(cand)} candidates)", "uids": []}
