# entity -> database table id (frozen mapping, scripts/t28_nation_tail.py REFS)
ENTITY_TID = {"continent": 5, "language": 8, "nation": 10, "region": 19,
              "currency": 41, "agreement": 56, "club": 3, "comp": 25,
              "stadium": 21, "city": 2, "local_region": 47, "weather": 27,
              "person": 1, "team": 23}
TYPE_WIDTH = {"integer": 4, "unique_id": 4, "real": 4, "enum": 1, "colour": 3,
              "string": None, "list": None, "database_record_unique_id": 4}


def slot_candidates(raw: bytes, archive: str, tid: int, xml: str, H: int, S: int,
                    n: int) -> dict:
    """Attach fields where the *domain* decides; everything else stays unmapped."""
    prof = {off: classify_column(raw, H, S, n, off) for off in range(S)}
    fields = entity(xml)["fields"]
    out: list[dict] = []
    used: set[int] = set()

    def take(off: int, width: int, field: str, grade: str, why: str) -> None:
        out.append({"field": field, "offset": off, "width": width,
                    "grade": grade, "why": why})
        used.add(off)

    # 1. identity triple -> rdui/duni (L2: structural, re-verified every row)
    q = None
    for off in range(S - 11):
        if all(_u32(raw, H + j * S + off) == j for j in range(0, n, max(1, n // 64))):
            q = off
            break
    if q is not None:
        take(q, 4, "rdui", "L2", "ordinal column equals row index for every sampled row")
        take(q + 4, 4, "duni", "L2",
             "UID pair u32==u32!=0; identical client/server for all rows")

    # 2. FK fields: a whole-u32 column whose value set lands inside a reference
    #    table's live UID domain. Rate must be 1.0 to be called a hit.
    for f in fields:
        if f.get("type") != "database_record_unique_id":
            continue
        ref = ENTITY_TID.get(f.get("database_table_type") or "")
        if ref is None or ref == tid:
            continue
        best = None
        for off in range(S - 3):
            if off in used:
                continue
            vals = column_values(raw, H, S, n, off, 4)
            if 0xFFFFFFFF in vals or 0 in vals:
                continue  # nullable sentinel lane -> not a clean FK column
            h = fk_hit(vals, archive, ref)
            if h.get("available") and h["rate"] == 1.0 and (best is None
                                                            or h["domain"] < best[1]["domain"]):
                best = (off, h)
        if best:
            take(best[0], 4, f["field"], "L2",
                 f"u32 domain subset of {f['database_table_type']} table_{ref} UIDs "
                 f"({best[1]['hit']}/{best[1]['rows']}, domain {best[1]['domain']})")
        else:
            out.append({"field": f["field"], "offset": None, "width": 4,
                        "grade": "unmapped",
                        "why": f"no u32 column hits {f['database_table_type']} "
                               f"(table_{ref}) UID domain at rate 1.0"})

    # 3. real fields: latitude/longitude style, plausibility + non-constant
    for f in fields:
        if f.get("type") != "real" or f["field"] in {o["field"] for o in out}:
            continue
        cands = []
        for off in range(S - 3):
            if off in used:
                continue
            c = prof[off]["f32"] if "f32" in prof[off] else None
            if not c or not prof[off].get("f32_plausible"):
                continue
            if len(set(column_f32(raw, H, S, n, off))) < max(2, n // 4):
                continue
            cands.append(off)
        if len(cands) == 1:
            take(cands[0], 4, f["field"], "L2",
                 "only non-constant plausible f32 column left after identity/FK")
        else:
            out.append({"field": f["field"], "offset": None, "width": 4,
                        "grade": "unmapped",
                        "why": f"{len(cands)} f32 columns remain viable; "
                               "domain does not decide"})

    # 4. enums: byte column whose domain is a scoped enum of the entity
    enum_names = set()
    for f in fields:
        if f.get("type") == "enum":
            enum_names.add(f["field"])
    for f in fields:
        if f.get("type") != "enum":
            continue
        picks = []
        for off in range(S):
            c = prof[off]
