        else:
            out.append({"field": f["field"], "offset": None, "width": 1,
                        "grade": "unmapped",
                        "why": f"{len(picks)} byte columns viable"})

    mapped = {o["field"] for o in out if o.get("offset") is not None}
    unmapped = [f["field"] for f in fields if f["field"] not in mapped]
    return {"archive": archive, "table": tid, "entity": xml,
            "header": H, "stride": S, "count": n,
            "slots": sorted(out, key=lambda o: (o["offset"] is None, o["offset"] or 0)),
            "unmapped": unmapped,
            "columns": {str(k): {kk: vv for kk, vv in v.items()
                                 if kk in ("u8_distinct", "u8_values", "all_zero",
                                           "all_ff", "u32", "f32", "f32_plausible")}
                        for k, v in prof.items()}}
